public E take() throws InterruptedException {
final ReentrantLock lock = this.lock;
lock.lockInterruptibly();
E result;
try {
while ( (result = dequeue()) == null)
// 无线等，要么有数据，要么中断线程
notEmpty.await();
} finally {
lock.unlock();
}
return result;
}

获取数据主要就是从数组中拿到0索引位置数据，然后保持二叉堆结构
private E dequeue() {
// 将元素个数-1，拿到了索引位置。
int n = size - 1;
// 判断是不是木有数据了，没数据直接返回null即可
if (n < 0)
return null;
// 说明有数据
else {
// 拿到数组，array
Object[] array = queue;
// 拿到0索引位置的数据
E result = (E) array[0];
// 拿到最后一个数据
E x = (E) array[n];
// 将最后一个位置置位null
array[n] = null;
Comparator<? super E> cmp = comparator;
if (cmp == null)
siftDownComparable(0, x, array, n);
else
siftDownUsingComparator(0, x, array, n, cmp);
// 元素个数-1，赋值size
size = n;
// 返回result
return result;
}
}

一定要以局部的方式去查看树结构的变化，他是从跟节点往下找较小的一个子节点，将较小的子节点
挪动到父节点位置，再将循环往下走，如果一来，整个二叉堆的结构就可以保证了。
// k：默认进来是0
// x：代表二叉堆的最后一个数据
// array：数组
// n：最后一个索引
private static <T> void siftDownComparable(int k, T x, Object[] array,int n) {
// 健壮性校验，取完第一个数据，已经没数据了，那就不需要做平衡操作
if (n > 0) {
// 拿到最后一个数据的比较器
Comparable<? super T> key = (Comparable<? super T>)x;
// 因为二叉堆是一个二叉满树，所以在保证二叉堆结构时，只需要做一半就可以
int half = n >>> 1;
// 做了超过一半，就不需要再往下找了。
while (k < half) {
// 找左子节点索引，一个公式，可以找到当前节点的左子节点
int child = (k << 1) + 1;
// 拿到左子节点的数据
Object c = array[child];
// 拿到右子节点索引
int right = child + 1;
// 确认有右子节点
// 判断左节点是否大于右节点
if (right < n && c.compareTo(array[right]) > 0)
// 如果左大于右，那么c就执行右
c = array[child = right];
// 比较最后一个节点是否小于当前的较小的子节点
if (key.compareTo((T) c) <= 0)
break;
// 将左右子节点较小的放到之前的父节点位置
array[k] = c;
// k重置到之前的子节点位置
k = child;
}
// 上面while循环搞定后，可以确认整个二叉堆中，数据已经移动ok了，只差当前k的位置数据是null
// 将最后一个索引的数据放到k的位置
array[k] = key;
}
}
五、DelayQueue

DelayQueue就是一个延迟队列，生产者写入一个消息，这个消息还有直接被消费的延迟时间。
需要让消息具有延迟的特性。
DelayQueue也是基于二叉堆结构实现的，甚至本事就是基于PriorityQueue实现的功能。二叉堆结
构每次获取的是栈顶的数据，需要让DelayQueue中的数据，在比较时，跟根据延迟时间做比较，剩
余时间最短的要放在栈顶。
查看DelayQueue类信息：
