清楚任务的流转流转状态是怎样的，其次对于核心属性要追到是干嘛的。
/**
FutureTask的核心属性
FutureTask任务的状态流转
NEW -> COMPLETING -> NORMAL 任务正常执行，并且返回结果也正常返回
NEW -> COMPLETING -> EXCEPTIONAL 任务正常执行，但是结果是异常
NEW -> CANCELLED 任务被取消
NEW -> INTERRUPTING -> INTERRUPTED 任务被中断
/
// 记录任务的状态
private volatile int state;
// 任务被构建之后的初始状态
private static final int NEW = 0;
private static final int COMPLETING = 1;
private static final int NORMAL = 2;
private static final int EXCEPTIONAL = 3;
private static final int CANCELLED = 4;
private static final int INTERRUPTING = 5;
private static final int INTERRUPTED = 6;
/** 需要执行任务，会被赋值到这个属性 */
private Callable<V> callable;
/** 任务的任务结果要存储在这几个属性中 */
private Object outcome; // non-volatile, protected by state reads/writes
/** 执行任务的线程 */
private volatile Thread runner;
/** 等待返回结果的线程Node对象， */
private volatile WaitNode waiters;
static final class WaitNode {
volatile Thread thread;
volatile WaitNode next;
WaitNode() { thread = Thread.currentThread(); }
}

任务执行前的一些判断，以及调用任务封装结果的方式，还有最后的一些后续处理
// 当线程池执行FutureTask任务时，会调用的方法
public void run() {
// 如果当前任务状态不是NEW，直接return告辞
if (state != NEW ||
// 如果状态正确是NEW，这边需要基于CAS将runner属性设置为当前线程
// 如果CAS失败，直接return告辞
!UNSAFE.compareAndSwapObject(this, runnerOffset, null, Thread.currentThread()))
return;
try {
// 将要执行的任务拿到
Callable<V> c = callable;
// 健壮性判断，保证任务不是null
// 再次判断任务的状态是NEW（DCL）
if (c != null && state == NEW) {
// 执行任务
// result：任务的返回结果
// ran：如果为true，任务正常结束。 如果为false，任务异常结束。
V result;
boolean ran;
try {
// 执行任务
result = c.call();
// 正常结果，ran设置为true
ran = true;
} catch (Throwable ex) {
// 如果任务执行期间出了异常
// 返回结果置位null
result = null;
// ran设置为false
ran = false;
// 封装异常结果
setException(ex);
}
if (ran)
// 封装正常结果
set(result);
}
} finally {
// 将执行任务的线程置位null
runner = null;
// 拿到任务的状态
int s = state;
// 如果状态大于等于INTERRUPTING
if (s >= INTERRUPTING)
// 进来代表任务中断，做一些后续处理
handlePossibleCancellationInterrupt(s);
}
}

任务执行完毕后，修改任务的状态以及封装任务的结果
// 没有异常的时候，正常返回结果
protected void set(V v) {
// 因为任务执行完毕，需要将任务的状态从NEW，修改为COMPLETING
if (UNSAFE.compareAndSwapInt(this, stateOffset, NEW, COMPLETING)) {
// 将返回结果赋值给 outcome 属性
outcome = v;
// 将任务状态变为NORMAL，正常结束
UNSAFE.putOrderedInt(this, stateOffset, NORMAL);
// 一会再说……
finishCompletion();
}
}
// 任务执行期间出现了异常，这边要封装结果
protected void setException(Throwable t) {
// 因为任务执行完毕，需要将任务的状态从NEW，修改为COMPLETING
if (UNSAFE.compareAndSwapInt(this, stateOffset, NEW, COMPLETING)) {
// 将异常信息封装到 outcome 属性
outcome = t;
// 将任务状态变为EXCEPTIONAL，异常结束
UNSAFE.putOrderedInt(this, stateOffset, EXCEPTIONAL);
// 一会再说……
finishCompletion();
}
}

任务取消的一个方式
任务直接从NEW状态转换为CANCEL
任务从NEW状态变成INTERRUPTING，然后再转换为INTERRUPTED
// 取消任务操作
public boolean cancel(boolean mayInterruptIfRunning) {
// 查看任务的状态是否是NEW，如果NEW状态，就基于传入的参数mayInterruptIfRunning
// 决定任务是直接从NEW转换为CANCEL，还是从NEW转换为INTERRUPTING
if (!(state == NEW &&
UNSAFE.compareAndSwapInt(this, stateOffset, NEW, mayInterruptIfRunning ? INTERRUPTING : CANCELLED)))
return false;
try {
// 如果mayInterruptIfRunning为true
// 就需要中断线程
if (mayInterruptIfRunning) {
try {
// 拿到任务线程
Thread t = runner;
if (t != null)
// 如果线程不为null，直接interrupt
t.interrupt();
} finally {
// 将任务状态设置为INTERRUPTED
UNSAFE.putOrderedInt(this, stateOffset, INTERRUPTED);
}
}
} finally {
// 任务结束后的一些处理~~ 一会看~~
finishCompletion();
}
return true;
}

这个是线程获取FutureTask任务执行结果的方法
// 拿任务结果
public V get() throws InterruptedException, ExecutionException {
// 获取任务的状态
int s = state;
// 要么是NEW，任务还没执行完
// 要么COMPLETING，任务执行完了，结果还没封装好。
if (s <= COMPLETING)
// 让当前线程阻塞，等待结果
s = awaitDone(false, 0L);
// 最终想要获取结果，需要执行report方法
return report(s);
}
// 线程等待FutureTask结果的过程
private int awaitDone(boolean timed, long nanos) throws InterruptedException {
// 针对get方法传入了等待时长时，需要计算等到什么时间点
final long deadline = timed ? System.nanoTime() + nanos : 0L;
// 声明好需要的Node，queued：放到链表中了么？
WaitNode q = null;
boolean queued = false;
for (;;) {
// 查看线程是否中断，如果中断，从等待链表中移除，甩个异常
if (Thread.interrupted()) {
removeWaiter(q);
throw new InterruptedException();
}
// 拿到状态
int s = state;
// 到这，说明任务结束了。
if (s > COMPLETING) {
if (q != null)
// 如果之前封装了WaitNode，现在要清空
q.thread = null;
return s;
}
// 如果任务状态是COMPLETING，这就不需要去阻塞线程，让步一下，等待一小会，结果就有了
else if (s == COMPLETING)
Thread.yield();
// 如果还没初始化WaitNode，初始化
else if (q == null)
q = new WaitNode();
// 没放队列的话，直接放到waiters的前面
else if (!queued)
queued = UNSAFE.compareAndSwapObject(this, waitersOffset,
q.next = waiters, q);
// 准备挂起线程，如果timed为true，挂起一段时间
else if (timed) {
// 计算出最多可以等待多久
nanos = deadline - System.nanoTime();
// 如果等待的时间没了
if (nanos <= 0L) {
// 移除当前的Node，返回任务状态
removeWaiter(q);
return state;
}
// 等一会
LockSupport.parkNanos(this, nanos);
}
else
// 死等
LockSupport.park(this);
}
}
// get的线程已经可以阻塞结束了，基于状态查看能否拿到返回结果
private V report(int s) throws ExecutionException {
// 拿到outcome 返回结果
Object x = outcome;
// 如果任务状态是NORMAL，任务正常结束，返回结果
if (s == NORMAL)
return (V)x;
// 如果任务状态大于等于取消
if (s >= CANCELLED)
// 直接抛出异常
throw new CancellationException();
// 到这就是异常结束
throw new ExecutionException((Throwable)x);
}

只要任务结束了，无论是正常返回，异常返回，还是任务被取消都会执行这个方法
而这个方法其实就是唤醒那些执行get方法等待任务结果的线程
// 任务结束后触发
private void finishCompletion() {
// 在任务结束后，需要唤醒
for (WaitNode q; (q = waiters) != null;) {
// 第一步直接以CAS的方式将WaitNode置为null
if (UNSAFE.compareAndSwapObject(this, waitersOffset, q, null)) {
for (;;) {
// 拿到了Node中的线程
Thread t = q.thread;
// 如果线程不为null
if (t != null) {
// 第一步先置位null
q.thread = null;
// 直接唤醒这个线程
LockSupport.unpark(t);
}
// 拿到当前Node的next
WaitNode next = q.next;
// next为null，代表已经将全部节点唤醒了吗，跳出循环
if (next == null)
break;
// 将next置位null
q.next = null;
// q的引用指向next
q = next;
}
break;
}
}
// 任务结束后，可以基于这个扩展方法，记录一些信息
done();
// 任务执行完，把callable具体任务置位null
callable = null;
}
